<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\Expense; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class ExpensePaymentController extends Controller { public function store(Request $request,Expense $expense){$data=$request->validate(['payment_date'=>'required|date','amount'=>'required|numeric|min:0.01','payment_method'=>'required','reference_number'=>'nullable','notes'=>'nullable']);return DB::transaction(function()use($expense,$data){$locked=Expense::with('payments')->lockForUpdate()->findOrFail($expense->id);$balance=max(0,$locked->amount-$locked->payments->sum('amount'));if($data['amount']>$balance)throw ValidationException::withMessages(['amount'=>'Payment cannot exceed the outstanding balance of ₹'.number_format($balance,2)]);return response()->json($locked->payments()->create($data),201);});} public function destroy(Expense $expense,int $payment){$expense->payments()->findOrFail($payment)->delete();return response()->noContent();} }
